#include "resident/domains/military/military_model.hpp"
// 原军事接触候选链：真实军团资格→原敌对军令→同一B轨迹交点→锚点合法性→稳定独占。
#include "military_contact.hpp"
#include "battle_world.hpp"
#include "resident/model/common_model.hpp"
#include <algorithm>
#include <set>
namespace hanmo::resident {
namespace {
template<class T>const T* find_id(const std::vector<T>& rows,const StableId& id){for(auto& r:rows)if(r.id==id)return &r;return nullptr;}
bool fit(const MilitaryState& s,const ArmyRecord& army){for(auto& id:army.unit_ids){auto unit=find_id(s.military_units,id);if(unit&&unit->army_id==army.id&&!unit->fit.empty()&&unit->morale>0)return true;}return false;}
// 原_aggessor按两军输入序检查实际征讨军令，异组织本身不构成敌对。
bool hostile(const MilitaryState& s,const MilitaryCatalog& c,const ArmyRecord& a,const ArmyRecord& b){if(a.organization_id==b.organization_id)return false;for(auto pair:{std::pair<const ArmyRecord*,const ArmyRecord*>{&a,&b},{&b,&a}}){auto campaign=find_id(s.campaigns,pair.first->order_id);auto definition=campaign?find_id(c.orders,campaign->template_id):nullptr;auto target=definition?find_id(c.strongholds,definition->target_stronghold_id):nullptr;if(!campaign||!definition||!target)continue;auto state=find_id(s.strongholds,target->id);auto camp=find_id(c.garrisons,target->garrison_id);StableId owner=state?state->owner_organization_id:(camp?camp->organization_id:StableId{});if(campaign->army_id==pair.first->id&&(campaign->status=="marching"||campaign->status=="operating")&&definition->objective_kind=="occupy"&&owner==pair.second->organization_id)return true;}return false;}
std::optional<terrain::Mode> mode(const StableId& m){if(m=="foot")return terrain::Mode::foot;if(m=="army")return terrain::Mode::army;if(m=="boat")return terrain::Mode::boat;return {};}
// 静止军团按army模式核点；移动军团仍须能从整数锚点续到真实剩余首段。
bool anchors_legal(const TravelCatalog& c,const TravelServices& services,const ContactHit& hit){for(auto endpoint:{&hit.first,&hit.second}){auto map=c.maps.find(endpoint->anchor.map_id);auto movement=endpoint->trace.stationary?std::optional<terrain::Mode>{terrain::Mode::army}:mode(endpoint->trace.params.mode);if(!map||!movement||!terrain::point_valid_prepared(*map,endpoint->anchor.point,*movement,services.terrain_flags()))return false;if(!endpoint->trace.stationary&&(endpoint->trace.params.points.empty()||!terrain::segment_cost_prepared(*map,endpoint->anchor.point,endpoint->trace.params.points.front(),*movement,{}).ok))return false;}return true;}
bool moved(const CommonRead& c,const TravelMotion& m){if(!m.moving)return false;auto actor=c.actor(m.actor_id);auto loc=actor?std::get_if<WildernessLocation>(&actor->location):nullptr;if(!loc)return false;PointI previous=loc->point;for(Integer i=0;i<m.reached_points&&i<static_cast<Integer>(m.params.points.size());++i){auto next=m.params.points[static_cast<std::size_t>(i)];if(next.x!=previous.x||next.y!=previous.y)return true;previous=next;}return m.end.x!=previous.x||m.end.y!=previous.y;}
}
// 只导出原军令判定供舟战接触复用；原陆军候选和先后顺序保持不变。
bool military_armies_hostile(const MilitaryState& s,const MilitaryCatalog& c,const ArmyRecord& a,const ArmyRecord& b){return hostile(s,c,a,b);}
bool capture_military_march(const CommonRead&,const MilitaryState& state,const MilitaryCatalog& catalog,const StableId& actor){auto army=active_army_for_actor(state,actor);return catalog.march_condition_model&&army&&army->status=="active"&&army->commander_actor_id==actor;}
Status check_military_march_execution(const MilitaryCatalog& catalog,const TerrainExecution& execution){if(!catalog.march_condition_model)return common_success();return military_capability_failure("actions_step","military_march",execution.action_id);}
Outcome<MilitaryContactProbe> probe_military_contacts(const CommonRead& common,const MilitaryState& state,const MilitaryCatalog& military,const TravelState& travel,const TravelCatalog& geography,const TravelServices& services,const std::vector<StableId>& hold){
    (void)military;MilitaryContactProbe result;if(geography.world_map_id.empty()||!geography.maps.find(geography.world_map_id))return {true,result,{}};
    // 本profile从未创建战斗或military_contact历史；任何该类输入在完整admission已明确拒绝，不能伪读为空。

    struct Eligible {const ArmyRecord* army;TravelMotion motion;};std::vector<Eligible> eligible;std::vector<const ArmyRecord*> armies;for(auto& army:state.armies)armies.push_back(&army);std::sort(armies.begin(),armies.end(),[](auto a,auto b){return a->id<b->id;});std::set<StableId> seen;
    for(auto army:armies){if(services.army_embarked(army->id)||army->status!="active"||std::find(hold.begin(),hold.end(),army->commander_actor_id)!=hold.end()||!fit(state,*army)||military_actor_in_battle(state,army->commander_actor_id))continue;auto person=common.actor(army->commander_actor_id);if(!person||!person->alive||!person->available)continue;std::optional<TravelMotion> trace;
        if(person->action_id.empty()){if(auto location=std::get_if<WildernessLocation>(&person->location))trace=stationary_terrain_trace(person->id,*location);}else{auto action=common.action(person->action_id);if(!action||action->kind!="travel"||action->actor_id!=person->id)continue;auto params=travel.actions.find(action->id);if(!params)return {false,{},military_capability_failure("contact_detect","military_legacy_travel",action->id).error};auto motion=terrain_motion(common,geography,services,*action,*params,hold);if(!motion.ok){if(motion.error.kind!=ErrorKind::rule)return {false,{},motion.error};continue;}trace=std::move(motion.value);}
        if(!trace||trace->map_id!=geography.world_map_id||!validate_terrain_trace(*trace).ok)continue;if(!seen.insert(person->id).second)return {true,MilitaryContactProbe{},{}};
        eligible.push_back({army,std::move(*trace)});
    }
    result.eligible_armies=eligible.size();ContactEntrances entrances;for(auto& settlement:geography.settlements.rows())entrances[geography.world_map_id].push_back(settlement.second.map_xy);
    std::vector<MilitaryContactHit> hits;for(std::size_t a=0;a<eligible.size();++a)for(std::size_t b=a+1;b<eligible.size();++b){++result.candidate_pairs;if(!hostile(state,military,*eligible[a].army,*eligible[b].army))continue;bool met=false;if(eligible[a].motion.stationary||eligible[b].motion.stationary){auto moving=eligible[a].motion.stationary?&eligible[b]:&eligible[a];auto still=eligible[a].motion.stationary?&eligible[a]:&eligible[b];for(auto& fact:state.contact_facts)if(fact.motion_sources){bool stationary_source=false,moving_source=false;for(auto& source:*fact.motion_sources){if(source.first==still->army->id)stationary_source=true;if(source.first==moving->army->id&&source.second.action_id==moving->motion.action_id&&!moving->motion.action_id.empty())moving_source=true;}if(stationary_source&&moving_source)met=true;}}if(met)continue;++result.exact_pairs;auto intersection=terrain_intersection(eligible[a].motion,eligible[b].motion,entrances);if(!intersection||!anchors_legal(geography,services,*intersection))continue;auto first=intersection->a==eligible[a].motion.actor_id?eligible[a].army:eligible[b].army;auto second=intersection->b==eligible[b].motion.actor_id?eligible[b].army:eligible[a].army;MilitaryContactHit hit;hit.source_tick=common.tick();hit.first_army_id=first->id;hit.second_army_id=second->id;hit.first_motion=intersection->a==eligible[a].motion.actor_id?eligible[a].motion:eligible[b].motion;hit.second_motion=intersection->b==eligible[b].motion.actor_id?eligible[b].motion:eligible[a].motion;hit.contact=std::move(*intersection);hits.push_back(std::move(hit));}
    std::sort(hits.begin(),hits.end(),[](auto& a,auto& b){return contact_before(a.contact,b.contact);});std::set<StableId> used;for(auto& hit:hits){if(used.count(hit.contact.a)||used.count(hit.contact.b))continue;used.insert(hit.contact.a);used.insert(hit.contact.b);result.ordered_hits.push_back(std::move(hit));}return {true,std::move(result),{}};
}
Status check_military_contact_capability(const CommonRead& common,const MilitaryState& state,const MilitaryCatalog& military,const TravelState& travel,const TravelCatalog& geography,const TravelServices& services,const std::vector<StableId>& hold){
    if(military.march_condition_model){auto ids=common.action_order();std::sort(ids.begin(),ids.end());for(auto& id:ids){auto action=common.action(id);if(!action||action->kind!="travel"||!capture_military_march(common,state,military,action->actor_id))continue;auto params=travel.actions.find(id);if(!params)return military_capability_failure("contact_detect","military_legacy_travel",id);auto motion=terrain_motion(common,geography,services,*action,*params,hold);if(!motion.ok)return {false,{},motion.error};if(moved(common,motion.value))return military_capability_failure("contact_detect","military_march",id);}}
    auto probe=probe_military_contacts(common,state,military,travel,geography,services,hold);if(!probe.ok)return {false,{},probe.error};if(!probe.value.ordered_hits.empty()){auto& hit=probe.value.ordered_hits.front();return military_capability_failure("contact_detect","military_contact",hit.first_army_id+"|"+hit.second_army_id);}return common_success();}
}
